            arg = msg.substring(_loc4_ + 1);
            msg = msg.substring(0,_loc4_);
         }
         if(msg == "" || msg == "Press_")
         {
            msg = "backgroundClick";
         }
         if(DDW.Managers.GameManager.getInstance().isGfx)
         {
            if(arg != null)
            {
               fscommand(msg,arg);
            }
            else
            {
               fscommand(msg,"");
            }
         }
         else if(arg != null)
         {
            trace("\'" + msg + "\', \'" + arg + "\'");
         }
         else
         {
            trace("\'" + msg + "\'");
         }
      }

}

